using ImageQualityEnhancer.Models;
using ImageQualityEnhancer.Services;

namespace ImageQualityEnhancer.Tests;

/// <summary>
/// End-to-end: C# workspace + worker client + real Python enhancement. Requires Python with OpenCV and NumPy.
/// Test images are generated by the worker's own test helpers so no binary fixtures are stored.
/// </summary>
public class WorkerEnhanceTests : IDisposable
{
    private static readonly TimeSpan Timeout = TimeSpan.FromSeconds(60);
    private readonly TempDirectory _root = new();
    private readonly JobWorkspace _workspace;

    public WorkerEnhanceTests()
    {
        _workspace = new WorkspaceManager(_root.Path).Create();
    }

    public void Dispose() => _root.Dispose();

    private string MakeNoisyPhoto(string fileName)
    {
        var path = _workspace.Resolve(WorkspaceFolder.Original, fileName);
        TestSamples.NoisyPhoto(path);
        return path;
    }

    [Fact]
    public async Task Enhance_WritesOutputAndThumbnailsInsideWorkspace()
    {
        var input = MakeNoisyPhoto("img_0001.png");
        var output = _workspace.Resolve(WorkspaceFolder.Enhanced, "img_0001.png");
        var thumbOriginal = _workspace.Resolve(WorkspaceFolder.Thumbnails, "img_0001_orig.jpg");
        var thumbEnhanced = _workspace.Resolve(WorkspaceFolder.Thumbnails, "img_0001_enh.jpg");
        var before = await File.ReadAllBytesAsync(input);

        await using var client = new PythonWorkerClient();
        await client.StartAsync();
        var result = await client.SendAsync("enhance", new
        {
            input,
            output,
            settings = new EnhancementSettings(),
            thumbnails = new { original = thumbOriginal, enhanced = thumbEnhanced, maxSide = 256 },
        }).WaitAsync(Timeout);

        Assert.Equal("completed", result.GetProperty("status").GetString());
        Assert.Equal(640, result.GetProperty("output").GetProperty("width").GetInt32());
        Assert.Equal(480, result.GetProperty("output").GetProperty("height").GetInt32());
        Assert.True(File.Exists(output));
        Assert.True(File.Exists(thumbOriginal));
        Assert.True(File.Exists(thumbEnhanced));
        Assert.Equal(before, await File.ReadAllBytesAsync(input));
    }

    [Fact]
    public async Task ManualSettings_AreHonouredByWorker()
    {
        var input = MakeNoisyPhoto("img_0002.png");
        await using var client = new PythonWorkerClient();
        await client.StartAsync();

        var result = await client.SendAsync("enhance", new
        {
            input,
            output = _workspace.Resolve(WorkspaceFolder.Enhanced, "img_0002.png"),
            settings = new EnhancementSettings { Mode = "manual", SharpenAmount = 0.5 },
        }).WaitAsync(Timeout);

        var ops = result.GetProperty("operations").EnumerateArray().Select(o => o.GetProperty("op").GetString()).ToList();
        Assert.Equal(["sharpen"], ops);
    }

    [Fact]
    public async Task OverBudgetImage_IsSkippedWithReason()
    {
        var input = MakeNoisyPhoto("img_0003.png");
        await using var client = new PythonWorkerClient();
        await client.StartAsync();

        var result = await client.SendAsync("enhance", new
        {
            input,
            output = _workspace.Resolve(WorkspaceFolder.Enhanced, "img_0003.png"),
            limits = new { maxPixels = 1000 },
        }).WaitAsync(Timeout);

        Assert.Equal("skipped", result.GetProperty("status").GetString());
        Assert.Equal("too_large", result.GetProperty("reason").GetString());
        Assert.False(File.Exists(_workspace.Resolve(WorkspaceFolder.Enhanced, "img_0003.png")));
    }

    [Fact]
    public async Task CorruptImage_FailsOnlyThatRequest()
    {
        var input = _workspace.Resolve(WorkspaceFolder.Original, "broken.jpg");
        await File.WriteAllBytesAsync(input, [0xFF, 0xD8, 0xFF, 0xE0, 0x00, 0x10, 0x4A, 0x46, 0x49, 0x46, 0x00]);
        await using var client = new PythonWorkerClient();
        await client.StartAsync();

        var ex = await Assert.ThrowsAsync<WorkerException>(() => client.SendAsync("enhance", new
        {
            input,
            output = _workspace.Resolve(WorkspaceFolder.Enhanced, "broken.jpg"),
        }));

        Assert.Equal("decode_failed", ex.Code);
        await client.SendAsync("ping").WaitAsync(Timeout);
    }
}
